// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(uint256 seed) public {
        // Full domain, no exclusions: derive the candidate owner from the fuzzed seed.
        // Fuzzers hit seed == 0 (a boundary value) with high probability, so address(0)
        // is an admissible and easily reachable target.
        address newOwner = address(uint160(seed));

        // Only the current owner (the test contract that deployed c) may call setOwner.
        vm.prank(address(this));
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }

        // Rule: for EVERY seed, an owner-issued setOwner succeeds and the public
        // owner getter equals exactly the requested address (zero included).
        // The mutant breaks this for seed == 0 by reverting on address(0).
        assertTrue(ok && c.owner() == newOwner);
    }
}
